import React , {useEffect, useState} from "react";

import "./styles.css"
import { getStore, parseDateMMDDYYYY, gen16CodeId, txtOrempty } from "../../../stores/Utils";
import {   delete_inventory, group_prod_stock, get_filter_by_mp } from "../services/server_fetching";
import { useNavigate } from "react-router";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt, CheckBoxSlide_Cmpt } from "../../../components";
import { NavLink } from "react-router-dom";


const Svg = SvgIcon_Cmpt();

const CheckBoxSlide = CheckBoxSlide_Cmpt();

const CompareComprobantesOnInventory  = ({ data, item }) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	const [cmpNBnk, setCmpNBnk] = useState(0);

	const loadProdStock =  (dat) => {
		group_prod_stock(dat,updObs);
	};


	
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			updObs();
			get_filter_by_mp(loadProdStock);
		}
	});


	const updObs =  () => {
		set_obs(gen16CodeId())
	}




	const navigate = useNavigate();

	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}
	


	let inv_comprobantes_compare = getStore("inv_comprobantes_compare");

	let data2Rend = inv_comprobantes_compare?.["hasError"];

	return (
		<div style={{
			maxHeight: "86vh",
			width: "1080px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "16px 19px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect">
					{"Comparacion Inventario y la cuenta de Inventario "}
				</p>
				<div className="flexSpace"/>
				<div className="_dsplFlx " style={{marginTop: 12}}>
					<CheckBoxSlide
						initvalue={cmpNBnk}
						keyCode={77}
						updChange={(e)=>setCmpNBnk(e)}
					/>
					<span className={`checklabel`}>
						{"Differencia mayor 1$"}
					</span>
				</div>
			</div>




			
			<div className="_dsplFlx hdr_bar purple" style={{marginTop: 14}}>
				<div className="tr_bar_5"/>
				<div className="tr_bar_15">
					Comprobante
				</div>
				<div className="tr_bar_15">
					Date
				</div>
				<div className="tr_bar_20">
					Document
				</div>
				<div className="tr_bar_15">
					Amount
				</div>
				<div className="tr_bar_15">
					Inventory Amount
				</div>
				<div className="tr_bar_15">
					Difference
				</div>
			</div>
			
			<div className="scollVh subMHeight" style={{height: "calc(85vh - 96px)"}}>
			{data2Rend && data2Rend?.map((element) => <ListingProducts key={element.operationId} element={element} idKey={element.inventoryId} close={close} ignoreSamllDiff={cmpNBnk} />)}
			</div>
		</div>
	);
};

export default CompareComprobantesOnInventory;



const ListingProducts  = ({ element, idKey, close, ignoreSamllDiff }) => {

	const deleteComprobante =  () => {
		delete_inventory(idKey, close);
	}

	let hasDiff = element.inventory;
	let diff = element.amount*1 - element.inventoryAmount*1;
	let diffAmount = diff.toFixed(2);

	if (ignoreSamllDiff){
		diff =  diff<0?diff*-1:diff;
		if(diff<1){
			return null;
		}
	}

	
	return (
		<div className="_dsplFlx hdr_bar">
			<div className="icon_compr tr_bar_5" >
				<Svg 
					name={hasDiff? "money": "alert"} 
					color={hasDiff? "var(--hrm_palette-color-orange-800)":"#c62828"}
				/>
			</div>
			<div className="tr_bar_15 comprobante_id"  onClick={()=>close()}>
					<NavLink to={{
						pathname: "/accounting-ledger" ,
						search: `?cId=${element.comprobanteId}`
					}}>
						{element.comprobanteId}
					</NavLink>
			</div>
			<div className="tr_bar_15">
				{element.date && parseDateMMDDYYYY(element.date)}
			</div>
			<div className="tr_bar_20">
				{element.document}
			</div>
			<div className="tr_bar_15">
				{txtOrempty((element.amount*1).toFixed(2))}
			</div>
			<div className="tr_bar_15">
				{txtOrempty(element.inventoryAmount*1)}
			</div>
			<div className="tr_bar_15">
				{txtOrempty((diffAmount*1))}
			</div>
			
			<div className=""/>
			
		</div>
	)

}




